pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 unlockTime, uint256 amount) public {
        // Keep amount admissible: >0, >= MinSum, and unlockTime in the past so Collect would proceed
        vm.assume(amount > 0);
        vm.assume(amount >= 1 ether);
        vm.assume(unlockTime < block.timestamp);

        // Deploy the adversarial callee that always rejects incoming ether via transfer
        Reverter reverter = new Reverter();

        // Fund the attacker and deposit into C to establish balance for the reverter address
        address attacker = address(reverter);
        vm.deal(attacker, amount);
        vm.prank(attacker);
        c.Put{value: amount}(unlockTime);

        // Record balance and log length BEFORE the Collect attempt
        (uint prevUnlockTime, uint prevBalance) = c.Acc(attacker);
        uint prevHistoryLength = c.LogFile().History_length();

        // Attempt to collect; because transfer will revert, the call should revert in BOTH versions,
        // but the original continues after a failed low-level call (returns false) and deducts balance,
        // while the mutant reverts the entire transaction, leaving balance and log unchanged.
        bool ok;
        try c.Collect(amount) { ok = true; } catch { ok = false; }

        // After a revert, the reference contract's state may have been modified; the buggy one's hasn't.
        // Property: IF the call reverted, THEN the original's balance was decreased AND a new log entry was added;
        // the buggy version, having reverted, will leave balance unchanged and log length unchanged.
        // The test observes: the balance is NOT equal to prevBalance OR the history length is NOT equal to prevHistoryLength.
        // For the original (no revert of state changes), balance and log DO change; for the buggy (full revert), they don't.
        assertTrue(!ok ? (c.Acc(attacker).balance != prevBalance || c.LogFile().History_length() != prevHistoryLength) : true);
    }
}

