pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0);
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(amount <= type(uint256).max / 2);

        // Deploy adversarial callee that reverts on receiving ether
        Reverter reverter = new Reverter();
        address payable wallet = payable(address(reverter));

        // Deposit funds into the contract so the actor has a balance
        uint256 depositAmt = amount + 1 ether;
        vm.deal(actor, depositAmt);
        vm.prank(actor);
        c.Put{value: depositAmt}(block.timestamp + 1);

        // Warp past unlock time
        vm.warp(block.timestamp + 2);

        // Set the actor's address as the caller
        vm.prank(actor);
        // The call should succeed in the correct contract (low-level call to reverter returns false),
        // but fail in the mutant (transfer reverts). We observe this via a try/catch.
        try c.Collect(amount) {
            // If we reach here, Collect did NOT revert.
            // In the correct contract, the balance should have decreased.
            uint256 balanceAfter = getBalance(actor);
            assertTrue(balanceAfter == depositAmt - amount);
        } catch {
            // If it reverted, the mutant didn't update balance.
            // We cannot assert here because the correct contract never reverts;
            // the assertion above already fails for the mutant because it reverts.
            // However, to satisfy the single-assert requirement, we use a catch that always passes
            // for the mutant and fails for the correct one.
            // So we'll invert the logic: we check that the revert did NOT happen.
            assertTrue(false);
        }
    }

    function getBalance(address actor) internal view returns (uint256) {
        (uint256 unlockTime, uint256 balance) = c.Acc(actor);
        return balance;
    }
}

