pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 unlockTime) public {
        // 1. Admissible domain: amount must be positive and sender must have enough balance
        vm.assume(amount > 0);

        // Deploy a reverter callee to force transfer failure
        Reverter reverter = new Reverter();

        // Fund the reverter so it has a balance to meet MinSum and withdrawal
        vm.deal(address(reverter), amount + c.MinSum());
        vm.warp(0);

        // Make the reverter deposit via Put to establish Acc balance
        vm.prank(address(reverter));
        c.Put{value: amount + c.MinSum()}(unlockTime);

        // Warp past unlock time to satisfy the timestamp condition
        uint256 effectiveUnlock = unlockTime > block.timestamp ? unlockTime : block.timestamp;
        vm.warp(effectiveUnlock + 1);

        // Record pre-balance
        uint256 preBalance = c.Acc(address(reverter)).balance;

        // The reverter's fallback reverts on ether receipt, causing the low-level call in Collect to fail.
        // In original C, the call failure is caught and the balance is still deducted.
        // In buggy M, transfer reverts the whole transaction.
        vm.prank(address(reverter));
        try c.Collect(amount) { /* reference continues, bug reverts */ } catch { /* reference does not catch, bug catches */ }

        uint256 postBalance = c.Acc(address(reverter)).balance;

        // 3. General rule: If the call did not revert entirely (i.e., Collect succeeded),
        // the balance must be reduced by amount. In reference, Collect always succeeds
        // (balance reduced); in buggy, it reverts (balance unchanged).
        // We check if the transaction reverted (postBalance unchanged) vs succeeded (postBalance reduced).
        // Since try/catch catches only EVM reverts from the external call, the reference's
        // internal call failure does NOT cause a revert; it continues and updates balance.
        // The buggy version's transfer fails and reverts the whole transaction, caught by try/catch.
        // This test asserts that after the try/catch, the balance is exactly preBalance - amount.
        // For the reference, this holds. For the buggy, it reverts so balance remains preBalance, failing the assertion.
        assertTrue(postBalance == preBalance - amount);
    }
}

