pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C(address(this));
    }
    function testFuzz_property(uint256 _am, address _caller) public {
        // Bound the collection amount to at least 2 ether so we have room to put and still meet MinSum after dealing
        _am = bound(_am, 2 ether, 10 ether);
        // Exclude blacklisted addresses
        vm.assume(_caller != address(0));
        vm.assume(_caller != address(c));
        vm.assume(_caller != address(this));

        // Deploy a reverter that will make the low-level call/transfer fail
        Reverter reverter = new Reverter();

        // Put enough ETH so reverter's Acc meets MinSum and has the collect amount
        vm.deal(address(reverter), _am);
        vm.prank(address(reverter));
        c.Put{value: _am}(0);
        // Warp past unlock time
        vm.warp(block.timestamp + 1);

        // Record pre-state
        uint256 preBalance = c.Acc(address(reverter)).balance;

        // Prank as the reverter (which will revert on incoming ETH)
        vm.prank(address(reverter));
        try c.Collect(_am) {
            // Reference: call succeeds and state is updated despite transfer failure
            assertTrue(false); // Should not reach here; the call should fail because transfer to reverter reverts
        } catch {
            // Buggy: transfer reverts entire transaction, state unchanged
            // Reference: transfer failure does not prevent state update; transaction succeeds
            // But in our setup prank(reverter) calls Collect, and the low-level call to msg.sender (reverter) reverts
            // Reference: call returns false, state still updates; transaction does NOT revert
            // Buggy: transfer reverts, transaction reverts entirely
            // So catch block is entered ONLY for buggy; for reference it would not catch
            // We cannot distinguish within a single catch whether it's reference or buggy.
            // Instead, we assert the state change.
        }

        uint256 postBalance = c.Acc(address(reverter)).balance;
        // Universal property: After a non-reverting Collect call, balance MUST be reduced by _am
        // In reference, the call never reverts, so postBalance = preBalance - _am always
        // In buggy, the call reverts, so postBalance = preBalance (state unchanged)
        // But since we cannot guarantee reference doesn't revert (it does not revert, but our try/catch catches failure)
        // We need an invariant that holds for reference and breaks for buggy.
        // Property: The balance after the call (whether reverted or not) is NOT equal to preBalance.
        // Reference: balance decreased -> postBalance != preBalance.
        // Buggy: balance unchanged -> postBalance == preBalance.
        assertTrue(postBalance != preBalance);
    }
}

