pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depAmount, uint256 collectAmount, uint256 unlockTime) public {
        // Keep deposits above MinSum and in a reasonable range
        depAmount = bound(depAmount, 1 ether, 1000 ether);
        collectAmount = bound(collectAmount, 1, depAmount);
        // Ensure unlockTime is in the past so collect is allowed
        vm.warp(1 days);
        unlockTime = bound(unlockTime, 0, block.timestamp - 1);

        address alice = address(0xA11CE);
        address bob = address(0xB0B);
        vm.deal(alice, depAmount);
        vm.deal(bob, depAmount);

        // alice deposits with an old unlockTime so her funds are available
        vm.prank(alice);
        c.Put{value: depAmount}(unlockTime);

        // bob deposits with a future unlockTime so his funds are locked
        vm.prank(bob);
        c.Put{value: depAmount}(block.timestamp + 100 days);

        // Record balances before collect
        (uint256 aliceUnlockBefore, uint256 aliceBalBefore) = c.Acc(alice);
        (, uint256 bobBalBefore) = c.Acc(bob);
        uint256 totalRecordedBalBefore = aliceBalBefore + bobBalBefore;
        uint256 contractBalBefore = address(c).balance;

        // alice collects _am (should succeed)
        vm.prank(alice);
        bool ok = true;
        try c.Collect(collectAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            // After a successful collect, the sum of all recorded balances must not exceed the contract's actual ether.
            // The reference subtracts alice's balance, so the invariant holds.
            // The buggy version keeps alice's balance unchanged while sending ether, causing total recorded balances
            // to eventually exceed contract ether.
            (, uint256 aliceBalAfter) = c.Acc(alice);
            (, uint256 bobBalAfter) = c.Acc(bob);
            uint256 sumRecordedBalAfter = aliceBalAfter + bobBalAfter;
            uint256 contractBalAfter = address(c).balance;
            assertTrue(contractBalAfter >= sumRecordedBalAfter);
        }
    }
}

