pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, uint256 unlockDelay) public {
        // Bound deposit amount to a reasonable range so the account doesn't overflow
        depositAmount = bound(depositAmount, 1, 100 ether);
        // Bound collect amount to at most depositAmount
        collectAmount = bound(collectAmount, 1, depositAmount);
        // Ensure unlock time is a future timestamp not too far into the future
        unlockDelay = bound(unlockDelay, 1, 365 days);

        address user = address(0xbeef);

        // Fund the user
        vm.deal(user, depositAmount);

        // The user deposits and sets an unlock time in the future
        vm.prank(user);
        c.Put{value: depositAmount}(block.timestamp + unlockDelay);

        // Record the balance after deposit (should be exactly depositAmount)
        uint256 balanceBefore = c.Acc(user).balance;

        // Warp to after the unlock time
        vm.warp(block.timestamp + unlockDelay + 1);
        // Start prank as the user for collecting
        vm.startPrank(user);

        try c.Collect(collectAmount) {
            // Collect succeeded
            vm.stopPrank();
            uint256 balanceAfter = c.Acc(user).balance;
            // The correct contract must have subtracted collectAmount from the user's balance
            assertEq(balanceAfter, balanceBefore - collectAmount);
        } catch {
            // Collect reverted, nothing changed; no assertion needed
            vm.stopPrank();
        }
    }
}

