contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint256 amount, uint8 reenterDepth) public {
        // bound to plausible values
        amount = bound(amount, 1, 1000 ether);
        unlockTime = bound(unlockTime, 1, type(uint64).max); // ensure in future
        reenterDepth = uint8(bound(reenterDepth, 1, 1));

        // Deploy re-entrant attacker that calls Put and catches revert
        ReentrantAttacker attacker = new ReentrantAttacker();
        vm.deal(address(attacker), amount * 2);

        // Record initial balance
        uint256 initialAccBalance = c.Acc(address(attacker)).balance;

        // Attack: attacker makes a call that re-enters Put
        attacker.attack(address(c), unlockTime, amount);

        // After the attack, check the balance
        uint256 finalAccBalance = c.Acc(address(attacker)).balance;

        // Property: If the Put call fails due to re-entrancy lock, the balance should not change.
        // In reference, require reverts before state changes; in buggy, assert panics and the attacker
        // can catch the panic and continue, potentially altering state.
        // Since the attacker calls Put twice, the second call should be blocked.
        // In reference, balance remains amount (first call succeeds).
        // In buggy, assert consumes all gas and attacker catches it, leading to no increase on second call but
        // the state changes may have been applied depending on the catch.
        // Actually the difference: in buggy, assert panics and attacker can catch and still have the first call's state change,
        // but the invariant is: after any sequence, the balance never exceeds total messages sent that successfully executed.
        // Here we assert that the final balance is exactly equal to the amount (only first call went through).
        // In reference, require reverts nicely, attacker can catch and continue, balance = amount.
        // In buggy, assert panics, attacker catches panic, but state changes may be applied if the panic is caught at the right level.
        // We want a property that holds for reference but fails for buggy.
        // Property: After the attack, if the contract is not locked, the attacker's balance should be exactly amount.
        // In reference: unlocked, balance == amount.
        // In buggy: unlocked? Actually assert consumes all gas, attacker's try-catch catches, but locked_ is already set to true before _; runs.
        // Let's craft: the attacker catches the panic and then calls again? No, only one re-enter.
        // Simpler: the re-entrant attacker makes Put revert during the second call, catching it.
        // The property: After any call to Put that is not the first call in a re-entrant sequence, the balance of the caller does not increase.
        // We can just assert that the final balance == amount.
        // In reference, require reverts, state changes of first call are committed, second call reverts, balance = amount.
        // In buggy, assert panics, first call's state changes are committed (since they happened before the re-entrant call),
        // but the panic consumes all gas and causes the entire top-level call to revert, undoing the first call's changes.
        // So in buggy, balance = 0 (reverted), in reference, balance = amount.
        // That's a valid difference: reference commits state on re-entrant failure, buggy reverts entirely due to panic.
        assertTrue(finalAccBalance == amount, "Balance mismatch");
    }
}

