        // ensure unlockTime is in the past
        vm.warp(block.timestamp + 365 days + 1);

        // drive Collect: low-level call to ReturnFalseReceiver returns false, does not revert
        vm.prank(bad);
        c.Collect(amt);

        // after Collect, the reference only deducts on _s == true, so balance stays preBal;
        // the mutant deducts before the call and never restores on _s == false.
        uint256 postBal = c.Acc(bad).balance;
        assertEq(postBal, preBal);
    }
}

// Helper that returns false on receiving Ether (does NOT revert)
contract ReturnFalseReceiver {
    fallback() external payable {
        // return false by returning empty data (EVM returns 0 on empty returndata for bool)
        assembly {
            return(0, 0)
        }
    }
}

