pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint112 depositAmount, uint112 collectAmount) public {
        // Ensure collectAmount <= depositAmount to keep the test in the admissible domain
        vm.assume(collectAmount <= depositAmount);
        vm.assume(depositAmount >= 1 ether);
        vm.assume(collectAmount > 0);

        address user = address(0x1234);
        vm.deal(user, depositAmount);
        vm.prank(user);
        c.Put{value: depositAmount}(block.timestamp);

        // Warp past unlock time
        vm.warp(block.timestamp + 1);

        uint256 balanceBefore = c.Acc(user);

        vm.prank(user);
        c.Collect(collectAmount);

        uint256 balanceAfter = c.Acc(user);
        assertTrue(balanceAfter == balanceBefore - collectAmount);
    }
}
